func TestLinuxProbeConnAwaitIsReleasedByContext(t *testing.T) {
	_, port := silentListener(t)
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	c, err := linuxProber{port: port}.open(ctx, loopback, 1)
	if err != nil {
		t.Fatal(err)
	}
