318	// errQueueMsg builds the control-message buffer Recvmsg returns for one
319	// IP_RECVERR error: a cmsghdr (SOL_IP, IP_RECVERR) then payload.
320	func errQueueMsg(level, typ int32, payload []byte) []byte {
321		buf := make([]byte, syscall.CmsgSpace(len(payload)))
322		h := (*syscall.Cmsghdr)(unsafe.Pointer(&buf[0]))
323		h.Level, h.Type = level, typ
324		h.SetLen(syscall.CmsgLen(len(payload)))
325		copy(buf[syscall.CmsgLen(0):], payload)
326		return buf
327	}
